import './index.less'

interface HeroProps {
  tag?: string
  title: string
  description: string
  ctaText?: string
  onCtaClick?: () => void
  images: string[]
}

const Hero = ({
  tag,
  title,
  description,
  ctaText,
  onCtaClick,
  images,
}: HeroProps) => {
  const useMarquee = images.length > 4
  const doubled = useMarquee ? [...images, ...images] : images

  return (
    <section className="hero">
      <div className="hero__content">
        {tag && <span className="hero__tag">{tag}</span>}
        <h1 className="hero__title">{title}</h1>
        <p className="hero__desc">{description}</p>
        {ctaText && (
          <button className="hero__cta" onClick={onCtaClick}>
            {ctaText} <span className="hero__cta-arrow">→</span>
          </button>
        )}
      </div>
      <div className={`hero__carousel ${useMarquee ? 'hero__carousel--marquee' : ''}`}>
        <div className={`hero__track ${useMarquee ? 'hero__track--animate' : ''}`}>
          {doubled.map((src, idx) => (
            <div className="hero__card" key={idx}>
              <img src={src} alt="" />
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}

export default Hero
