import './index.less'

interface CaseCard {
  tag: string
  title: string
  desc?: string
  image?: string
  highlight?: boolean
  icons?: string[]
}

interface CaseCardsProps {
  cards: CaseCard[]
}

const CaseCards = ({ cards }: CaseCardsProps) => {
  return (
    <div className="case-cards">
      {cards.map((card, idx) => (
        <div
          key={idx}
          className={`case-cards__card ${
            card.highlight ? 'case-cards__card--highlight' : ''
          }`}
        >
          <div className="case-cards__body">
            <div className="case-cards__top">
              <span
                className={`case-cards__tag ${card.highlight ? 'case-cards__tag--highlight' : ''}`}
              >
                {card.tag}
              </span>
              {!!card.icons?.length && (
                <div className="case-cards__icons" aria-hidden>
                  {card.icons.map((icon, iconIdx) => (
                    <span className="case-cards__icon" key={`${idx}-${iconIdx}`}>
                      <img src={icon} alt="" />
                    </span>
                  ))}
                </div>
              )}
            </div>
            <div className="case-cards__info">
              <h3 className="case-cards__title">{card.title}</h3>
              {card.desc && <p className="case-cards__desc">{card.desc}</p>}
            </div>
          </div>
          {card.image && (
            <div className="case-cards__media">
              <img src={card.image} alt={card.title} />
            </div>
          )}
        </div>
      ))}
    </div>
  )
}

export default CaseCards
